{% schema %}
{"name":"Selected bases","tag":"section","settings":[{"type":"text","label":"Heading","default":"Another starting point","id":"title"},{"type":"text","label":"Description","default":"Each product is sold separately.","id":"subtitle"},{"type":"product","label":"First product","id":"product1"},{"type":"product","label":"Second product","id":"product2"},{"type":"range","label":"Desktop columns","default":2,"min":2,"max":3,"step":1,"id":"columns"},{"type":"range","label":"Products to show","default":2,"min":1,"max":8,"step":1,"id":"productLimit"}],"blocks":[],"presets":[{"name":"Selected bases","settings":{},"blocks":[]}],"enabled_on":{"templates":["*"]},"disabled_on":{"templates":[]}}
{% endschema %}

